import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFile } from 'node:fs/promises';
import { join, extname } from 'node:path';

const port = Number(process.env.PORT || 8080);
const dbPath = process.env.DB_PATH || './workboard.sqlite';
const database = new DatabaseSync(dbPath);
database.exec(`CREATE TABLE IF NOT EXISTS projects (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  archived INTEGER NOT NULL DEFAULT 0
)`);
try { database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
database.exec(`CREATE TABLE IF NOT EXISTS tasks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  completed INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
)`);
try { database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
const publicDirectory = join(import.meta.dirname, 'public');
const mimeTypes = { '.html': 'text/html; charset=utf-8', '.js': 'text/javascript; charset=utf-8', '.css': 'text/css; charset=utf-8' };

function sendJson(response, status, value) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

const server = http.createServer(async (request, response) => {
  const url = new URL(request.url, `http://${request.headers.host || 'localhost'}`);
  if (request.method === 'GET' && url.pathname === '/health') return sendJson(response, 200, { status: 'ok' });
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, database.prepare(`SELECT p.id, p.name, p.archived,
      COUNT(t.id) AS totalCount, COALESCE(SUM(t.completed), 0) AS completedCount
      FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
      GROUP BY p.id ORDER BY p.id`).all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = database.prepare('INSERT INTO projects (name) VALUES (?)').run(name);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), name });
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch && request.method === 'GET') {
    const projectId = Number(tasksMatch[1]);
    if (!database.prepare('SELECT 1 FROM projects WHERE id = ?').get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    return sendJson(response, 200, database.prepare('SELECT id, title, completed, priority FROM tasks WHERE project_id = ? ORDER BY id').all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
  }
  if (tasksMatch && request.method === 'POST') {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      const title = typeof data.title === 'string' ? data.title.trim() : '';
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      const projectId = Number(tasksMatch[1]);
      const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(projectId);
      if (!project) return sendJson(response, 404, { error: 'Project not found' });
      if (project.archived) return sendJson(response, 409, { error: 'Archived project' });
      const result = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)').run(projectId, title);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), title, completed: false });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (archiveMatch && request.method === 'POST') {
    const result = database.prepare('UPDATE projects SET archived = ? WHERE id = ?').run(archiveMatch[2] === 'archive' ? 1 : 0, Number(archiveMatch[1]));
    return result.changes ? sendJson(response, 200, { archived: archiveMatch[2] === 'archive' }) : sendJson(response, 404, { error: 'Project not found' });
  }
  const taskMatch = url.pathname.match(/^\/api\/tasks\/(\d+)$/);
  if (taskMatch && request.method === 'PATCH') {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      if (typeof data.completed !== 'boolean') return sendJson(response, 400, { error: 'Invalid completion state' });
      const task = database.prepare('SELECT tasks.id, projects.archived FROM tasks JOIN projects ON projects.id = tasks.project_id WHERE tasks.id = ?').get(Number(taskMatch[1]));
      if (!task) return sendJson(response, 404, { error: 'Task not found' });
      if (task.archived) return sendJson(response, 409, { error: 'Archived project' });
      database.prepare('UPDATE tasks SET completed = ? WHERE id = ?').run(data.completed ? 1 : 0, Number(taskMatch[1]));
      return sendJson(response, 200, { completed: data.completed });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  const taskRenameMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/rename$/);
  if (request.method === 'PATCH' && taskRenameMatch) {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      const title = typeof data.title === 'string' ? data.title.trim() : '';
      if (!title) return sendJson(response, 400, { error: 'Task title is required' });
      const task = database.prepare('SELECT tasks.id, projects.archived FROM tasks JOIN projects ON projects.id = tasks.project_id WHERE tasks.id = ?').get(Number(taskRenameMatch[1]));
      if (!task) return sendJson(response, 404, { error: 'Task not found' });
      if (task.archived) return sendJson(response, 409, { error: 'Archived project' });
      database.prepare('UPDATE tasks SET title = ? WHERE id = ?').run(title, Number(taskRenameMatch[1]));
      return sendJson(response, 200, { title });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  const taskPriorityMatch = url.pathname.match(/^\/api\/tasks\/(\d+)\/priority$/);
  if (request.method === 'PATCH' && taskPriorityMatch) {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      if (!['Low', 'Normal', 'High'].includes(data.priority)) return sendJson(response, 400, { error: 'Invalid task priority' });
      const task = database.prepare('SELECT tasks.id, projects.archived FROM tasks JOIN projects ON projects.id = tasks.project_id WHERE tasks.id = ?').get(Number(taskPriorityMatch[1]));
      if (!task) return sendJson(response, 404, { error: 'Task not found' });
      if (task.archived) return sendJson(response, 409, { error: 'Archived project' });
      database.prepare('UPDATE tasks SET priority = ? WHERE id = ?').run(data.priority, Number(taskPriorityMatch[1]));
      return sendJson(response, 200, { priority: data.priority });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectMatch) {
    try {
      let body = '';
      for await (const chunk of request) body += chunk;
      const data = JSON.parse(body);
      const name = typeof data.name === 'string' ? data.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0').run(name, Number(projectMatch[1]));
      if (result.changes) return sendJson(response, 200, { id: Number(projectMatch[1]), name });
      const project = database.prepare('SELECT archived FROM projects WHERE id = ?').get(Number(projectMatch[1]));
      return project ? sendJson(response, 409, { error: 'Archived project' }) : sendJson(response, 404, { error: 'Project not found' });
    } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
  }
  if (request.method === 'GET' && projectMatch) {
    const project = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?').get(Number(projectMatch[1]));
    if (project) project.archived = Boolean(project.archived);
    return project ? sendJson(response, 200, project) : sendJson(response, 404, { error: 'Project not found' });
  }
  if (request.method === 'GET') {
    const requested = url.pathname === '/' || url.pathname.startsWith('/projects/') ? 'index.html' : url.pathname.slice(1);
    if (requested.includes('..') || requested.includes('/')) { response.writeHead(404).end(); return; }
    try {
      const content = await readFile(join(publicDirectory, requested));
      response.writeHead(200, { 'content-type': mimeTypes[extname(requested)] || 'application/octet-stream' });
      response.end(content);
    } catch { response.writeHead(404).end('Not found'); }
    return;
  }
  response.writeHead(405).end();
});

server.listen(port, '0.0.0.0');

const listView = document.querySelector('#project-list');
const detailView = document.querySelector('#project-detail');
const projectContainer = document.querySelector('#projects');
const errorMessage = document.querySelector('#error-message');
const taskMessage = document.createElement('p');
taskMessage.id = 'task-error';
taskMessage.setAttribute('role', 'alert');
taskMessage.hidden = true;
document.querySelector('#project-detail').append(taskMessage);
let activeProjectId = null;
let projectTasks = [];

async function loadTasks() {
  const response = await fetch(`/api/projects/${activeProjectId}/tasks`);
  if (!response.ok) throw new Error('Could not load tasks');
  projectTasks = await response.json();
  renderTasks();
}

function renderTasks() {
  const container = document.querySelector('#tasks');
  const filter = document.querySelector('#task-filter').value;
  const priorityFilter = document.querySelector('#priority-filter').value;
  container.replaceChildren();
  for (const task of projectTasks) {
    if (filter === 'Open' && task.completed || filter === 'Completed' && !task.completed) continue;
    if (priorityFilter !== 'All' && task.priority !== priorityFilter) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'task-row';
    row.className = 'task-row';
    const title = document.createElement('span');
    title.textContent = task.title;
    const checkbox = document.createElement('input');
    checkbox.type = 'checkbox';
    checkbox.checked = task.completed;
    checkbox.disabled = Boolean(window.currentProjectArchived);
    checkbox.setAttribute('aria-label', `Complete ${task.title}`);
    checkbox.addEventListener('change', async () => {
      const response = await fetch(`/api/tasks/${task.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ completed: checkbox.checked }) });
      if (response.ok) { task.completed = checkbox.checked; renderTasks(); }
      else showTaskError('Unable to update task');
    });
    const priority = document.createElement('select');
    priority.setAttribute('aria-label', 'Task priority');
    for (const value of ['Low', 'Normal', 'High']) {
      const option = document.createElement('option');
      option.value = value;
      option.textContent = value;
      priority.append(option);
    }
    priority.value = task.priority || 'Normal';
    priority.disabled = Boolean(window.currentProjectArchived);
    priority.addEventListener('change', async () => {
      const response = await fetch(`/api/tasks/${task.id}/priority`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ priority: priority.value }) });
      if (response.ok) {
        task.priority = priority.value;
        renderTasks();
      } else showTaskError('Unable to update task priority');
    });
    const renameInput = document.createElement('input');
    renameInput.type = 'text';
    renameInput.value = task.title;
    renameInput.setAttribute('aria-label', 'New task title');
    renameInput.disabled = Boolean(window.currentProjectArchived);
    const renameButton = document.createElement('button');
    renameButton.type = 'button';
    renameButton.textContent = 'Rename task';
    renameButton.disabled = Boolean(window.currentProjectArchived);
    renameButton.addEventListener('click', async () => {
      const newTitle = renameInput.value.trim();
      if (!newTitle) { showTaskError('Task title is required'); return; }
      const response = await fetch(`/api/tasks/${task.id}/rename`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title: newTitle }) });
      if (!response.ok) { showTaskError('Unable to rename task'); return; }
      task.title = newTitle;
      renderTasks();
    });
    row.append(title, renameInput, renameButton, priority, checkbox);
    container.append(row);
  }
}

function showTaskError(message) {
  taskMessage.textContent = message;
  taskMessage.hidden = false;
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  const projects = await response.json();
  const filter = document.querySelector('#project-filter').value;
  projectContainer.replaceChildren();
  for (const project of projects) {
    if (filter === 'Active' && project.archived || filter === 'Archived' && !project.archived) continue;
    const row = document.createElement('div');
    row.dataset.testid = 'project-row';
    row.className = 'project-row';
    const name = document.createElement('span');
    name.textContent = project.name;
    const open = document.createElement('button');
    open.type = 'button';
    open.textContent = 'Open project';
    open.addEventListener('click', () => navigate(`/projects/${project.id}`));
    const summary = document.createElement('span');
    summary.dataset.testid = 'project-summary';
    summary.textContent = `${project.completedCount}/${project.totalCount} completed`;
    const action = document.createElement('button');
    action.type = 'button';
    action.textContent = project.archived ? 'Restore project' : 'Archive project';
    action.addEventListener('click', async () => {
      const response = await fetch(`/api/projects/${project.id}/${project.archived ? 'restore' : 'archive'}`, { method: 'POST' });
      if (response.ok) await loadProjects();
    });
    row.append(name, summary, open, action);
    projectContainer.append(row);
  }
}

async function renderRoute() {
  const match = location.pathname.match(/^\/projects\/(\d+)\/?$/);
  if (!match) {
    listView.hidden = false;
    detailView.hidden = true;
    await loadProjects();
    return;
  }
  const response = await fetch(`/api/projects/${match[1]}`);
  if (!response.ok) {
    navigate('/');
    return;
  }
  const project = await response.json();
  activeProjectId = project.id;
  document.querySelector('#project-title').textContent = project.name;
  const renameForm = document.querySelector('#rename-form');
  renameForm.querySelectorAll('input, button').forEach(control => { control.disabled = project.archived; });
  document.querySelector('#new-project-name').value = project.name;
  document.querySelector('#rename-error').hidden = true;
  window.currentProjectArchived = project.archived;
  document.querySelector('#archived-message').hidden = !project.archived;
  document.querySelector('#task-form').querySelectorAll('input, button').forEach(control => { control.disabled = project.archived; });
  listView.hidden = true;
  detailView.hidden = false;
  taskMessage.hidden = true;
  document.querySelector('#task-filter').value = 'All';
  document.querySelector('#priority-filter').value = 'All';
  await loadTasks();
}

function navigate(path) {
  history.pushState({}, '', path);
  renderRoute().catch(showLoadError);
}

function showLoadError() {
  errorMessage.textContent = 'Unable to load projects';
  errorMessage.hidden = false;
}

document.querySelector('#create-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const input = document.querySelector('#project-name');
  const name = input.value.trim();
  if (!name) {
    errorMessage.textContent = 'Project name is required';
    errorMessage.hidden = false;
    return;
  }
  errorMessage.hidden = true;
  try {
    const response = await fetch('/api/projects', {
      method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }),
    });
    if (!response.ok) throw new Error('Could not create project');
    input.value = '';
    await loadProjects();
  } catch { showLoadError(); }
});

document.querySelector('#rename-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const input = document.querySelector('#new-project-name');
  const name = input.value.trim();
  const error = document.querySelector('#rename-error');
  if (!name) { error.textContent = 'Project name is required'; error.hidden = false; return; }
  try {
    const response = await fetch(`/api/projects/${activeProjectId}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }) });
    if (!response.ok) throw new Error('Could not rename project');
    document.querySelector('#project-title').textContent = name;
    input.value = name;
    error.hidden = true;
  } catch { error.textContent = 'Unable to rename project'; error.hidden = false; }
});
document.querySelector('#task-form').addEventListener('submit', async (event) => {
  event.preventDefault();
  const input = document.querySelector('#task-title');
  const title = input.value.trim();
  if (!title) { showTaskError('Task title is required'); return; }
  taskMessage.hidden = true;
  try {
    const response = await fetch(`/api/projects/${activeProjectId}/tasks`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }) });
    if (!response.ok) throw new Error('Could not create task');
    input.value = '';
